// to 40 units along the horizontal axis and 60 units along the vertical axis. The// size of this rectangle is 30 units along the vertical axis and 20 units along the // horizontal axis. It encloses the points (20,30) and (40,60).// If myRect represents a rectangle on the screen, it is 30 pixels high and 20 pixels // wide, starting 30 pixels below and 20 pixels to the right of the upper-left corner// of the screen. NOTE: Several methods in CRect assume screen coordinates, in which// the top of the rectangle has a lower value than the bottom of the rectangle.// The fields are defined as short (16-bit) integers. Use VRect objects if you need to// represent rectangles in 32-bit coordinates.// The following operators allow you to do arithmetic on rectangles and set or retrieve// the value of the top-left or bottom-right corner of a rectangle://   Operator    Description		Example//   + and +=    Add CRects			CRect myRect = aCRect + CRect(15,10,30,20);//                                  myRect += CPoint(10,10);//   - and -=    Subtract CRects    CRect myRect = aCRect - CRect(12,20,24,40);//                                  myRect -= CPoint(10,10);//   &           Intersect CRects   CRect smallerCRect(thisCRect & thatCRect);//   |           Union CRects       CRect biggerCRect = thisCRect | thatCRect;//   []          Select corner      CPoint top_left = myRect[topLeft];//                                  myRect[botRight] = CPoint(100,100);// The following operators allow you to test the relationship between two points://   Operator      Description		//   ==            The two rectangles are equivalent//   !=            The two rectangles are not equivalent//   The following additional methods are provided for manipulating rectangles://   Method        Description//   Contains      Test if a point or rectangle lies within this rectangle.//   Copy          Return a copy of this rectangle.//   Empty         Test if this rectangle is empty.//   GetLength     Return the length of this rectangle along the horiz or vert axis.//   Inset         Inset this rectangle.//   Valid         Test if this rectangle is valid.//   Validate      Switch the coordinates to make this rectangle valid, if necessary.// The CRect class also provides a cast from a CRect to a character string. This cast// can be useful in debugging.{public:	// CONSTRUCTORS:	CRect_AC() { Clear(); }	CRect_AC(short iLeft, short iTop, short iRight, short iBottom) { top = iTop; left = iLeft; bottom = iBottom; right = iRight; }	CRect_AC(const CPoint_AC& topLeftPt, const CPoint_AC& botRightPt) { *(CPoint_AC*)&top = topLeftPt; *(CPoint_AC*)&bottom = botRightPt; }	#if qMSWindows	CRect_AC(const RECT& rect) {top = rect.top; left = rect.left; bottom = rect.bottom; right = rect.right; }#endif#if qPowerPC	CRect_AC(const CRect_AC& rect)		{ top = rect.top; left = rect.left; bottom = rect.bottom; right = rect.right; }#endif	CRect_AC(const Rect& rect) { *this = *(const CRect_AC*)&rect; }#if qPowerPC	CRect_AC& operator=(const CRect_AC& rect)		{ top = rect.top; left = rect.left; bottom = rect.bottom; right = rect.right; return *this; }#endif			// SELECTION:		CPoint_AC& operator[](PointSelector sel) { return reinterpret_cast<CPoint_AC *>(&top)[sel]; }	const CPoint_AC& operator[](PointSelector sel) const { return reinterpret_cast<const CPoint_AC *>(&top)[sel]; }	// CONVERSION:	#if qDebug	CString_AC AsText() const;	operator CString_AC() const { return AsText(); }		// For converting CRect_AC to a textual representation of a CRect_AC. "CRect_AC(left,top,right,bottom)".#endif		operator Rect*() { return this; }	operator const Rect*() const { return this; }	// ARITHMETIC:	CRect_AC& operator+=(const CRect_AC& rt);	CRect_AC& operator-=(const CRect_AC& rt);	CRect_AC& operator*=(const CRect_AC& rt);	CRect_AC& operator/=(const CRect_AC& rt);	CRect_AC operator+(const CRect_AC& rt) const;	CRect_AC operator-(const CRect_AC& rt) const;	CRect_AC operator*(const CRect_AC& rt) const;	CRect_AC operator/(const CRect_AC& rt) const;	CRect_AC& operator+=(const CPoint_AC& pt);	CRect_AC& operator-=(const CPoint_AC& pt);	CRect_AC& operator*=(const CPoint_AC& pt);	CRect_AC& operator/=(const CPoint_AC& pt);	CRect_AC operator+(const CPoint_AC& pt) const;	CRect_AC operator-(const CPoint_AC& pt) const;	CRect_AC operator*(const CPoint_AC& pt) const;	CRect_AC operator/(const CPoint_AC& pt) const;		CRect_AC operator-() const;	// COMPARISON:	bool operator==(const CRect_AC& rt) const;	bool operator!=(const CRect_AC& rt) const { return !(*this == rt); }	// GEOMETRY:	short Width() const { return right - left; }	short Height() const { return bottom - top; }	CPoint_AC Middle() const { return CPoint_AC((left + right) / 2, (top + bottom) / 2); }	CRect_AC& operator&=(const CRect_AC& rt);	CRect_AC& operator|=(const CRect_AC& rt);	CRect_AC operator&(const CRect_AC& rt) const;	CRect_AC operator|(const CRect_AC& rt) const;	// Two simple area operators, the intersection & (bitwise and in C++) and the	// union | (bitwise or in C++). The definition of union here is to return a CRect_AC	// that exactly encloses its operands.			// UTILITY:	CRect_AC AsRect() const { return CRect_AC(*this); }		// Creates a CRect_AC by casting the VCoordinate values to short values. In other		// words, it throws away the top 16 bits of each long word value. If the values		// don't fit within 16 bits you will get strange results (i.e. 32769 -> 1). 		// Danger: Don't use this in TView methods for converting from view space to QD		// space. Instead, use TView::ViewToQDRect()!		// ADDED TO CRect_AC FOR ORTHOGONALITY	CRect_AC ToRect() const { return CRect_AC(*this); }		// Creates a CRect_AC by limiting the VCoordinate values to +/- 32K and casting		// them to short values. This produces reasonable results if the values were		// more than 16 bits (i.e. 32769 -> 32767). 		// Danger: Don't use this in TView methods for converting from view space to QD		// space. Instead, use TView::ViewToQDRect()!		// ADDED TO CRect_AC FOR ORTHOGONALITY		void Clear() { *(long*)&top = *(long*)&bottom = 0; }	void Set(short iLeft, short iTop, short iRight, short iBottom) { top = iTop; left = iLeft; bottom = iBottom; right = iRight; }	void Set(const CPoint_AC& topLeftPt, short width, short height);	void Set(const CPoint_AC& topLeftPt, const CPoint_AC& botRightPt) { *(CPoint_AC*)&top = topLeftPt; *(CPoint_AC*)&bottom = botRightPt; }		void Offset(short iH, short iV);	void Offset(const CPoint_AC& delta) { *this+= delta; }	void Inset(short iH, short iV);	void Inset(const CPoint_AC& delta);	void Inset(const CRect_AC& delta);	bool IsEmpty() const;	bool Empty() const { return IsEmpty(); }	// Return true if the VRect is empty (right - left = 0 and bottom - top = 0)		bool IsValid() const;	bool Valid() const { return IsValid(); }	// Returns true if a valid rectangle (left < right and top < bottom).			void Validate();	// Validate rectagle by switching the points if right-bottom is above or to the    // left of left-top.			short GetLength(VHSelect sel) const;	// Returns the length of a CRect_AC in a given dimension.		CPoint_AC GetSize() const;	// Returns the size of a CRect_AC in both dimensions. (a CPoint_AC)		bool Contains(const CPoint_AC& pt) const;	bool Contains(const CRect_AC& rt) const;	// The Contains method takes either a CPoint_AC or a CRect_AC and returns true if the operand	// is inside of the CRect_AC the method is applied to.protected:	short Min(const short a, const short b) const { return a < b ? a : b; }	short Max(const short a, const short b) const { return a > b ? a : b; }	short MinMax(short MinVal, short expression, short MaxVal) const { return Min(Max(expression, MinVal), MaxVal); }			// CONSTANTS:	public:	static const CRect_AC kZeroRect;};#endif // __CRect_AC__